import {esc} from './organiser-utils.js';
export function attention(review={},failed=false,now=Date.now()){
 const future=review.stage==='interview'&&review.interview_published&&Date.parse(review.interview_at)>now;
 return {booking:review.stage==='interview'&&(!review.interview_published||!review.interview_at),followup:review.stage==='interview'&&review.interview_published&&Date.parse(review.interview_at)+(review.duration_minutes||30)*60000<=now,review:['new','under_review'].includes(review.stage||'new'),interviews:future,unanswered:future&&!review.interview_reply,reschedule:future&&review.interview_reply==='reschedule',email:failed};
}
export async function reviewExtras(host,sb,id,isCurrent){
 host.innerHTML='<p role="status">Loading interview feedback and onboarding…</p>';
 const [feedback,onboarding]=await Promise.all(['elan_interview_feedback','elan_member_onboarding'].map(t=>sb.from(t).select('*').eq('enquiry_id',id).maybeSingle()));
 if(!isCurrent())return;
 if(feedback.error||onboarding.error){host.textContent='Interview feedback and onboarding need the recruitment-readiness.sql upgrade.';return;}
 const groups=[['elan_interview_feedback','Private interview feedback','Visible only to the administrator, Director and Assistant Director. Saving feedback does not select the applicant or email them.',feedback.data,[['interviewer','Interviewer'],['department_fit','Department fit'],['availability','Availability and commitments'],['skills','Relevant skills'],['recommendation','Recommendation'],['comments','Additional comments (optional)']]],['elan_member_onboarding','Prepare their first day','Save the brief before selecting the applicant. It becomes visible in their organiser workspace only after selection and access activation.',onboarding.data,[['reporting_person','Reporting person and contact'],['responsibilities','Responsibilities'],['first_tasks','First tasks and deadlines'],['documents','Required documents and where to submit them (optional)'],['meeting_at','First meeting date and time (optional, your local time)'],['meeting_details','First meeting joining details (optional)']]]];
 host.innerHTML=groups.map(([table,title,intro,data,fields])=>'<details class="readiness-paper"><summary>'+title+'</summary><p>'+intro+'</p><form data-extra="'+table+'">'+fields.map(([key,label])=>'<label>'+label+(key==='meeting_at'?'<input type="datetime-local" name="meeting_at" value="'+(data?.meeting_at?new Date(new Date(data.meeting_at)-new Date(data.meeting_at).getTimezoneOffset()*60000).toISOString().slice(0,16):'')+'">':key==='recommendation'?'<select name="'+key+'" required><option value="">Choose a recommendation</option>'+['Proceed','Discuss','Do not proceed'].map(v=>'<option '+(data?.[key]===v?'selected':'')+'>'+v+'</option>').join('')+'</select>':'<textarea name="'+key+'" rows="3" maxlength="'+({interviewer:150,department_fit:1500,availability:1000,skills:1500,reporting_person:200,meeting_details:2000}[key]||3000)+'" '+(['comments','documents','meeting_details'].includes(key)?'':'required')+'>'+esc(data?.[key]||'')+'</textarea>')+'</label>').join('')+'<button>Save '+(table.includes('feedback')?'feedback':'onboarding brief')+'</button><p role="status"></p></form></details>').join('');
 for(const f of host.querySelectorAll('form')){f.oninput=()=>f.dataset.dirty='true';f.onsubmit=async e=>{e.preventDefault();if(f.inert||!f.reportValidity())return;f.inert=true;const out=f.querySelector('[role=status]');try{const values=Object.fromEntries([...new FormData(f)].map(([k,v])=>[k,v.trim()]));if('meeting_at' in values)values.meeting_at=values.meeting_at?new Date(values.meeting_at).toISOString():null;const r=await sb.from(f.dataset.extra).upsert({enquiry_id:id,...values,updated_at:new Date().toISOString()});if(r.error)throw r.error;f.dataset.dirty='false';out.textContent='Saved.';}catch(err){out.textContent=err.message;}finally{f.inert=false;}};}
}
export async function onboardingView(host,sb,context={}){
 const r=await sb.rpc('elan_my_onboarding');
 if(context.isCurrent&&!context.isCurrent())return;
 if(r.error){host.innerHTML='<h2>Your onboarding</h2><p>Your brief could not load. Please contact the organising team.</p>';return;}
 if(context.isCurrent&&!context.isCurrent())return;const o=r.data?.[0];host.innerHTML='<header class="ops-head"><small>START HERE / ÉLAN 2027</small><h2>Welcome to the team.</h2><p>'+esc(context.department||'Summit leadership')+' · '+esc(context.role||'Organiser')+'</p></header>'+(o?['reporting_person','responsibilities','first_tasks','documents'].map((k,i)=>'<section><h3>'+['Your reporting person','Your responsibilities','Your first tasks','Documents to prepare'][i]+'</h3><p style="white-space:pre-wrap">'+esc(o[k]||'No documents requested.')+'</p></section>').join(''):'<section class="ops-paper"><h3>Your department contact</h3><p>'+esc(context.heads?.length?context.heads.join(', '):'Ask summit leadership to confirm your reporting person.')+'</p><p>Your personalised brief has not been published yet. Open Briefings & resources for your department brief, or ask your lead before starting work.</p></section>')+'<section class="ops-paper"><h3>Your next meeting</h3><p>'+esc(o?.meeting_at?new Date(o.meeting_at).toLocaleString():'No joining meeting has been shared yet.')+'</p><p style="white-space:pre-wrap">'+esc(o?.meeting_details||'Check with your reporting person before making arrangements.')+'</p></section>'+((context.tasks||[]).length?'<section class="ops-paper"><h3>Start with this task</h3><h4>'+esc(context.tasks[0].title)+'</h4><p>'+esc(context.tasks[0].brief||'Open the task for its details.')+'</p><p>'+esc(context.tasks[0].due_on?'Due '+context.tasks[0].due_on:'No deadline set')+'</p><button data-go="tasks">Open my tasks ↗</button></section>':'<section class="ops-paper"><h3>Your first assignment</h3><p>No open task is assigned to you yet. Ask your reporting person what to start with.</p></section>')+'<p>Use My tasks for progress updates and Briefings & resources for department documents.</p>';
 const checklist=document.createElement('div');host.append(checklist);const {welcomeChecklist}=await import('./member-welcome.js');await welcomeChecklist(checklist,sb,context);
}
